'use strict';
const test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const os=require('node:os');const path=require('node:path');const {Readable}=require('node:stream');const {createHash}=require('node:crypto');const {DatabaseSync}=require('node:sqlite');const {spawnSync}=require('node:child_process');
const source=process.env.REPORTING_SERVICE||'/workspace/scratch/2ea1ba0f2164/v082-authority-20261031/candidate/reporting/runtime/vector-reporting-service.cjs';const Reporting=require(source);
async function call(service,url,body){const req=Readable.from([Buffer.from(JSON.stringify(body))]);req.method='POST';req.url=url;req.headers={cookie:'wfm_session=peer'};const res={statusCode:200,setHeader(){},end(v){this.body=JSON.parse(String(v));}};assert.equal(await service.handleRequest(req,res),true);return res;}
function setup(){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'v082-boundary-'));const dbPath=path.join(dir,'wfm.sqlite');const db=new DatabaseSync(dbPath);db.exec('CREATE TABLE users(email TEXT PRIMARY KEY,tenant TEXT NOT NULL,role TEXT NOT NULL);CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,email TEXT NOT NULL,expires INTEGER NOT NULL);CREATE TABLE identity_tenant_control(tenant TEXT PRIMARY KEY,privileged_freeze INTEGER);');db.prepare('INSERT INTO users VALUES(?,?,?)').run('a@example.test','a','payroll_admin');db.prepare('INSERT INTO sessions VALUES(?,?,?)').run(createHash('sha256').update('peer').digest('hex'),'a@example.test',Date.now()+3600000);db.close();const x={dir,dbPath,reads:0,armed:false,hook:null};x.service=Reporting.createVectorReportingService({dbPath,currentUserReader:({email,tenant})=>{if(x.armed&&++x.reads===3&&x.hook)x.hook();return {email,tenant,role:'payroll_admin'};}});x.close=()=>{x.service.close();fs.rmSync(dir,{recursive:true,force:true});};return x;}
function mutate(x,sql){const db=new DatabaseSync(x.dbPath);try{db.exec(sql);}finally{db.close();}}
async function schedule(x){const report=await call(x.service,'/api/reporting/reports',{definition:{title:'Peer boundary fixture',sourceId:'payroll-control'}});assert.equal(report.statusCode,201);const plan=await call(x.service,'/api/reporting/schedules',{reportId:report.body.report.id,cadence:'daily',hour:16,minute:5,timeZone:'UTC',delivery:'in_app'});assert.equal(plan.statusCode,201);return plan.body.schedule;}
const due=new Date('2026-09-24T16:05:00Z');
test('unchanged local authority still produces one READY across repeated runs',async()=>{const x=setup();try{await schedule(x);x.armed=true;const result=await x.service.runDueSchedules(due);assert.equal(result.length,1);assert.equal(result[0].status,'READY');assert.deepEqual(await x.service.runDueSchedules(due),[]);}finally{x.close();}});
test('a local freeze committed immediately before BEGIN fences a stale reader grant',async()=>{const x=setup();const exec=DatabaseSync.prototype.exec;let reached=false;try{await schedule(x);DatabaseSync.prototype.exec=function(sql){if(sql==='BEGIN IMMEDIATE'&&!reached){reached=true;mutate(x,"INSERT INTO identity_tenant_control VALUES('a',1)");}return exec.call(this,sql);};x.armed=true;const result=await x.service.runDueSchedules(due);assert.equal(reached,true);assert.equal(result[0].status,'BLOCKED_AUTHORITY_DRIFT');}finally{DatabaseSync.prototype.exec=exec;x.close();}});
test('a separate process cannot commit revocation after the final local authority read until publication commits',async()=>{const x=setup();const prepare=DatabaseSync.prototype.prepare;let reached=false;try{await schedule(x);DatabaseSync.prototype.prepare=function(sql){const st=prepare.call(this,sql);if(sql!=='SELECT email,tenant,role FROM users WHERE tenant=? AND email=?')return st;return {get(...args){const actor=st.get(...args);if(x.armed&&!reached){reached=true;const child=spawnSync(process.execPath,['-e',"const{DatabaseSync}=require('node:sqlite');const db=new DatabaseSync(process.argv[1]);try{db.exec(\"UPDATE users SET role='employee'\");process.stdout.write('COMMITTED');}catch(e){process.stdout.write(e.message);}finally{db.close();}",x.dbPath],{encoding:'utf8',timeout:3000});assert.equal(child.status,0,child.stderr);assert.match(child.stdout,/locked|busy/);assert.doesNotMatch(child.stdout,/COMMITTED/);}return actor;}};};
// Recreate service so the prepared user statement receives the observation hook.
x.service.close();x.service=Reporting.createVectorReportingService({dbPath:x.dbPath,currentUserReader:({email,tenant})=>({email,tenant,role:'payroll_admin'})});x.armed=true;const result=await x.service.runDueSchedules(due);assert.equal(reached,true);assert.equal(result[0].status,'READY');mutate(x,"UPDATE users SET role='employee'");const next=await x.service.runDueSchedules(new Date('2026-09-25T16:05:00Z'));assert.equal(next[0].status,'BLOCKED_AUTHORITY_DRIFT');}finally{DatabaseSync.prototype.prepare=prepare;x.close();}});
test('blocked local-authority receipt failure rolls back and releases same-slot claim',async()=>{const x=setup();try{await schedule(x);mutate(x,"CREATE TRIGGER peer_refuse BEFORE INSERT ON vector_report_deliveries BEGIN SELECT RAISE(ABORT,'peer receipt fault'); END");x.hook=()=>mutate(x,"UPDATE users SET role='employee'");x.armed=true;await assert.rejects(x.service.runDueSchedules(due),/peer receipt fault/);mutate(x,"DROP TRIGGER peer_refuse; UPDATE users SET role='payroll_admin'");x.armed=false;const result=await x.service.runDueSchedules(due);assert.equal(result.length,1);assert.equal(result[0].status,'READY');const db=new DatabaseSync(x.dbPath);try{assert.equal(db.prepare('SELECT count(*) n FROM vector_report_deliveries').get().n,1);assert.equal(db.prepare('SELECT count(*) n FROM vector_report_delivery_intents').get().n,0);assert.equal(db.prepare('SELECT count(*) n FROM vector_report_delivery_observations').get().n,0);}finally{db.close();}}finally{x.close();}});

